import React, { ReactElement } from 'react';
import { DivFlexColumn, DivFlexRow, StyledLabel } from './elements/formelements';
import TextInputWithIcon from './TextInputWithIcon';


interface TextInputProps {
    label?: string;
    ariaLabel: string;
    value: string;
    onChange: (value: string) => void;
    placeholder?: string;
    readOnly?: boolean;
    icon?: ReactElement | string;
    validate?: any
}

const TextInputLabeled: React.FC<TextInputProps> = ({
    label,
    ariaLabel,
    value,
    onChange,
    placeholder,
    readOnly = false,
    icon,
    validate
}) => {

    return (
        <DivFlexRow>
            {label && (
                <DivFlexColumn>
                    <StyledLabel>
                        {label}
                    </StyledLabel>
                </DivFlexColumn>
            )}
            <DivFlexColumn fullWidth>
                <TextInputWithIcon
                    ariaLabel={ariaLabel}
                    value={value}
                    onChange={onChange}
                    placeholder={placeholder}
                    readOnly={readOnly}
                    icon={icon}
                    validate={validate}
                />
            </DivFlexColumn>
        </DivFlexRow>
    );
};

export default TextInputLabeled;
